<script setup lang="ts">const open=ref(false);const {settings,loadSettings}=usePublicContent();const {isDark}=useThemeMode();await loadSettings();const {data:menus}=await useFetch('/api/public/menus',{default:()=>[]});const links=computed(()=>menus.value?.filter((x:any)=>x.location==='header'&&x.status==='active').sort((a:any,b:any)=>(a.order||0)-(b.order||0)).map((x:any)=>[x.label,x.url])||[]);watch(()=>useRoute().fullPath,()=>open.value=false)</script>
<template><div><a class="skip-link" href="#main-content">Saltar para o conteúdo</a><header class="am-nav"><div class="am-wrap am-nav__inner"><NuxtLink to="/" :aria-label="`${settings.name} — início`"><img class="am-nav__logo" :src="isDark ? '/brand/logo-branco.png' : '/brand/logo-preto.png'" :alt="settings.brand||settings.name"></NuxtLink><nav class="am-nav__links" aria-label="Navegação principal"><NuxtLink v-for="link in links" :key="link[1]" :to="link[1]">{{link[0]}}</NuxtLink><NuxtLink class="am-nav__cta" :to="settings.contactCtaUrl">{{settings.contactCtaLabel}}</NuxtLink></nav><button class="am-menu" :aria-expanded="open" aria-label="Abrir menu" @click="open=!open"><Icon :name="open?'lucide:x':'lucide:menu'" size="26"/></button></div><nav v-if="open" class="am-mobile-panel" aria-label="Navegação móvel"><NuxtLink v-for="link in links" :key="link[1]" :to="link[1]">{{link[0]}}</NuxtLink><NuxtLink class="am-nav__cta" :to="settings.contactCtaUrl">{{settings.contactCtaLabel}}</NuxtLink></nav></header></div></template>
